/*!
 * Bootstrap Table of Contents v1.0.1 (http://afeld.github.io/bootstrap-toc/)
 * Copyright 2015 Aidan Feldman
 * Licensed under MIT (https://github.com/afeld/bootstrap-toc/blob/gh-pages/LICENSE.md)
 *
 * Patched: rewrote heading detection and nav generation.
 * - Uses the real heading hierarchy, including page h1 titles
 * - Child lists always visible (no display:none)
 */
!function ($) {
  "use strict";

  window.Toc = {
    helpers: {
      findHeadings: function ($scope, level) {
        return $scope.find("h" + level).filter(":not([data-toc-skip])");
      },

      findHeadingsInOrder: function ($scope, topLevel, maxLevel) {
        return $scope
          .find("h1,h2,h3,h4")
          .filter(":not([data-toc-skip])")
          .filter(function (_, el) {
            var level = parseInt(el.tagName.charAt(1), 10);
            return level >= topLevel && level <= maxLevel;
          });
      },

      generateAnchor: function (el) {
        if (el.id) return el.id;
        var base = $(el).text().trim()
          .replace(/[^\w\u4e00-\u9fff\s-]/g, "")
          .replace(/\s+/g, "-")
          .substring(0, 64)
          .replace(/^-+|-+$/g, "")
          .toLowerCase();
        if (!base) base = "section";
        var id = base, n = 0;
        while (document.getElementById(id)) { id = base + "-" + (++n); }
        el.id = id;
        return id;
      },

      createNavList: function () {
        return $('<ul class="nav navbar-nav"></ul>');
      },

      createChildNavList: function ($parent) {
        var $ul = this.createNavList();
        $parent.append($ul);
        return $ul;
      },

      ensureChildList: function ($item) {
        var $child = $item.children("ul.nav").first();
        if (!$child.length) $child = this.createChildNavList($item);
        return $child;
      },

      generateNavEl: function (id, text, level) {
        var $a = $('<a class="nav-link"></a>').attr("href", "#" + id).text(text);
        return $("<li></li>").addClass("toc-level-" + level).append($a);
      },

      generateNavItem: function (el) {
        var id = this.generateAnchor(el);
        var text = $(el).data("toc-text") || $(el).text();
        return this.generateNavEl(id, text, this.getNavLevel(el));
      },

      getTopLevel: function ($scope) {
        for (var lvl = 1; lvl <= 4; lvl++) {
          if (this.findHeadings($scope, lvl).length >= 1) return lvl;
        }
        return 1;
      },

      getNavLevel: function (el) {
        return parseInt(el.tagName.charAt(1), 10);
      },

      populateNav: function ($rootList, topLevel, $headings) {
        var self = this;
        var stack = [{ level: topLevel - 1, $list: $rootList, $item: null }];

        $headings.each(function (_, el) {
          var level = self.getNavLevel(el);
          if (level < topLevel) return;

          var $item = self.generateNavItem(el);
          while (stack.length > 1 && level <= stack[stack.length - 1].level) {
            stack.pop();
          }

          var parent = stack[stack.length - 1];
          var $targetList;
          if (parent.$item && level > parent.level) {
            $targetList = self.ensureChildList(parent.$item);
          } else {
            $targetList = parent.$list;
          }

          $targetList.append($item);
          stack.push({ level: level, $list: $targetList, $item: $item });
        });
      },

      parseOps: function (opts) {
        var ops = opts.jquery ? { $nav: opts } : opts;
        ops.$scope = ops.$scope || $(document.body);
        return ops;
      },

      init: function (opts) {
        opts = this.parseOps(opts);
        opts.$nav.attr("data-toggle", "toc");
        var $list = this.createChildNavList(opts.$nav);
        var topLvl = this.getTopLevel(opts.$scope);
        var $headings = this.findHeadingsInOrder(opts.$scope, topLvl, Math.min(topLvl + 2, 4));
        this.populateNav($list, topLvl, $headings);
      }
    },

    init: function (opts) {
      this.helpers.init.call(this.helpers, opts);
    }
  };

  $(function () {
    $('nav[data-toggle="toc"]').each(function (_, el) {
      Toc.init($(el));
    });
  });
}(jQuery);
